package com.dispatch.driver.core.model.device

import com.dispatch.driver.core.model.status.StatusDeclaration
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import java.util.Base64

/**
 * The device's statements and signatures, byte for byte as biz-kit makes them
 * (`device-signing-vectors.json`, generated by `CoopSubstrate.Canonical`,
 * `CoopSubstrate.Crypto` and `Dispatch.Accounts.DeviceKeys`).
 */
class DeviceSigningTest {

    private val vectors: JsonObject = Json.parseToJsonElement(
        checkNotNull(javaClass.classLoader?.getResource("device-signing-vectors.json")).readText(),
    ).jsonObject

    private fun bytes(value: String) = Base64.getUrlDecoder().decode(value)
    private fun JsonObject.text(key: String) = getValue(key).jsonPrimitive.content

    private val key = DeviceKey.fromSeed(bytes(vectors.text("seed")))

    @Test
    fun `the public key is the one the seed derives`() {
        assertArrayEquals(bytes(vectors.text("public_key")), key.publicKey)
    }

    @Test
    fun `the registration statement and its proof are biz-kit's`() {
        val registration = vectors.getValue("registration").jsonObject
        val statement = DeviceStatements.registration(
            tenantId = registration.text("tenant_id"),
            participantId = registration.text("participant_id"),
            installationId = registration.text("installation_id"),
            publicKey = key.publicKey,
        )

        assertArrayEquals(bytes(registration.text("statement")), statement)
        assertArrayEquals(bytes(registration.text("proof")), key.sign(statement))
    }

    @Test
    fun `an event's statement and signature are biz-kit's, from the body's own fields`() {
        val event = vectors.getValue("event").jsonObject
        val statement = DeviceStatements.event(event.getValue("fields").jsonObject)

        assertArrayEquals(bytes(event.text("statement")), statement)
        assertArrayEquals(bytes(event.text("signature")), key.sign(statement))
    }

    @Test
    fun `a declaration signed by the device is the body biz-kit verifies`() {
        val fields = vectors.getValue("event").jsonObject.getValue("fields").jsonObject
        val device = SigningDevice(fields.text("device_id"), key)
        val declaration = StatusDeclaration(
            eventId = fields.text("event_id"),
            status = fields.text("status"),
            occurredAt = fields.text("occurred_at"),
            note = fields.text("note"),
            deviceSequence = fields.getValue("device_sequence").jsonPrimitive.content.toLong(),
        )

        val body = Json.parseToJsonElement(declaration.signedBy(device).toCanonicalJson()).jsonObject

        assertEquals(vectors.getValue("event").jsonObject.text("signature"), body.text("device_signature"))
        assertEquals(fields, JsonObject(body - "device_signature"))
        // Queued once, sent unchanged: the signature survives the round trip.
        assertEquals(declaration.signedBy(device), StatusDeclaration.fromCanonicalJson(declaration.signedBy(device).toCanonicalJson()))
    }

    @Test
    fun `heads take their shortest form, at every boundary`() {
        val cases = mapOf(
            0L to "00", 23L to "17", 24L to "1818", 255L to "18ff", 256L to "190100",
            65_535L to "19ffff", 65_536L to "1a00010000", 4_294_967_296L to "1b0000000100000000",
            -1L to "20", -24L to "37", -25L to "3818", Long.MIN_VALUE to "3b7fffffffffffffff",
        )
        for ((value, hex) in cases) assertEquals("$value", hex, Canonical.encode(value).hex())
    }

    @Test
    fun `map keys sort by their encoded bytes, so a shorter key comes first`() {
        assertEquals(
            "a2" + "6162" + "01" + "626161" + "02",
            Canonical.encode(mapOf("aa" to 2L, "b" to 1L)).hex(),
        )
    }

    @Test
    fun `text, bytes, lists, booleans and null encode as CBOR's own types`() {
        assertEquals("63c3a965", Canonical.encode("ée").hex())
        assertEquals("420102", Canonical.encode(byteArrayOf(1, 2)).hex())
        assertEquals("83f5f4f6", Canonical.encode(listOf(true, false, null)).hex())
    }

    @Test
    fun `what has no canonical form is refused`() {
        for (value in listOf<Any>(1.5, 1.5f, Any(), mapOf(1 to 2))) {
            assertThrows(value.toString(), IllegalArgumentException::class.java) { Canonical.encode(value) }
        }
    }

    private fun ByteArray.hex() = joinToString("") { "%02x".format(it) }
}
